        public List<StatementSMAModel> GetStatementSMA(StatementSMACriteria criteria)
        {
            List<StatementSMAModel> statementList = new List<StatementSMAModel>();
            try
            {
                DataSet dataSet = new DataSet();
                using (var db = new ObjectDb(criteria.GetSettingKey()))
                {
                    var paramsOuput = criteria.GetSpParams();
                    dataSet = db.ExecuteDataSet(paramsOuput);
                }

                if (dataSet != null
                   && dataSet.Tables.Count > 0)
                {
                    double accumAmount = 0;
                     DataTable transTable = dataSet.Tables[0];
                     foreach (DataRow r in transTable.Rows)
                     {
                             var amount = Converter.To<double>(r["totalamt"]);
                             StatementSMAModel statementTmp = new StatementSMAModel
                             {
                                 No = Converter.To<int>(r["RowNum"]),
                                 TransType = Converter.To<string>(r["transtype"]),
                                 TransDesc = Converter.To<string>(r["transdesc"]),
                                 Total = Converter.To<double>(amount)
                             };

                             DateTime winlossDatetmp = CastAide.AsDateTime(r["matchdate"]);
                             statementTmp.WinlossDate = statementTmp.IsAccummulated ? "--" : winlossDatetmp.DayOfWeek + " <br> " + winlossDatetmp.ToString();

                             if (statementTmp.IsOpeningBalance)
                             {
                                 if (accumAmount == 0.0)
                                 {
                                     statementTmp.AccumulatedTotalString = "<div style=\"color: #4CC552;\" class=\"b\">OK</div>";
                                     statementTmp.AccumulatedTotalExcel = "OK";
                                 }
                                 else
                                 {
                                     var diffAmount = NumberFormat.DoubleFormat(amount - accumAmount, 6);
                                     if (diffAmount == "0.000000")
                                     {
                                         statementTmp.AccumulatedTotalString = "<div style=\"color: #4CC552;\" class=\"b\">OK</div>";
                                         statementTmp.AccumulatedTotalExcel = "OK";
                                     }
                                     else
                                     {
                                         statementTmp.AccumulatedTotalString = "NOT EQUAL <br>" + "<div class=\"b\" style=\"overflow: hidden;width:110px;\">RESET Total<br>Diff: " + diffAmount + "</div>";
                                         statementTmp.AccumulatedTotalExcel = "NOT EQUAL - RESET Total - Diff: " + diffAmount;
                                     }
                                     statementTmp.AccumulatedTotalNumber = amount - accumAmount;
                                 }
                                 accumAmount = amount;

                             }
                             else
                             {
                                 accumAmount = amount + accumAmount;
                                 statementTmp.AccumulatedTotalString = IBCUtils.FormatHandler.FormatNumber20(accumAmount);
                                 statementTmp.AccumulatedTotalExcel = IBCUtils.FormatHandler.FormatNumber20(accumAmount);
                                 statementTmp.AccumulatedTotalNumber = Math.Round(accumAmount, 2);


                             }
                             statementList.Add(statementTmp);
                         }
                     
                }
            }
            catch (Exception ex)
            {
                LoggingHandler.Log(ex);
            }
            return statementList;
        }

        public MemoryStream ExportExcelStatementSMA(StatementSMACriteria criteria, List<StatementSMAModel> data)
        {
            if (data == null)
            {
                data = (List<StatementSMAModel>)GetStatementSMA(criteria);
            }

            StatementReportExcelService _reportService = new StatementReportExcelService();

            return _reportService.ExportExcelSMAStatement(criteria, data);
        }

        public List<StatementMemberModel> GetStatementMember(StatementMemberCriteria criteria)
        {
            List<StatementMemberModel> statementList = new List<StatementMemberModel>();
            try
            {
                var statementRawData = GetListData<dynamic>(criteria);

                if (statementRawData != null)
                {
                    var accumAmount = 0.0;
                    int index = 1;
                    foreach (var row in statementRawData)
                    {
                        
                        StatementMemberModel statementTmp = new StatementMemberModel
                        {
                            No = index++,
                            TransType = Converter.To<string>(row.transtype),
                            TransDesc = Converter.To<string>(row.transdesc),
                            Commission = Converter.To<double>(row.commission)
                        };

                        DateTime winlossDatetmp = CastAide.AsDateTime(row.winlostdate);
                        statementTmp.WinlossDate = statementTmp.IsAccummulated ? "--" : winlossDatetmp.DayOfWeek + " <br> " + winlossDatetmp.ToString();
                        if (DateTime.Compare(winlossDatetmp, criteria.BalanceUpDay) < 0 && string.Compare(statementTmp.TransType, "bet", true) == 0)
                        {
                            statementTmp.TurnOver = "--";
                        }
                        else
                        {
                            statementTmp.TurnOver = IBCUtils.FormatHandler.FormatNumber20(Converter.To<double>(row.turnover));
                        }
                        statementTmp.Credit = (statementTmp.IsOpeningBalance == true) || (string.Compare(statementTmp.TransDesc, "Outstanding Bet", true) == 0) ? 0 : Converter.To<double>(row.totalAmt);
                        statementTmp.Total = statementTmp.IsOpeningBalance == true ? Converter.To<double>(row.totalAmt) : statementTmp.Total + statementTmp.Credit + statementTmp.Commission;
                        var amount = statementTmp.Total;
                        if (statementTmp.IsOpeningBalance)
                        {
                            if (accumAmount == 0.0)
                            {
                                statementTmp.AccumulatedTotalString = "<div style=\"color: #4CC552;\" class=\"b\">OK</div>";
                                statementTmp.AccumulatedTotalExcel = "OK";
                            }
                            else
                            {
                                var diffAmount = NumberFormat.DoubleFormat(amount - accumAmount, 6);
                                if (diffAmount == "0.000000")
                                {
                                    statementTmp.AccumulatedTotalString = "<div style=\"color: #4CC552;\" class=\"b\">OK</div>";
                                    statementTmp.AccumulatedTotalExcel = "OK";
                                }
                                else
                                {
                                    statementTmp.AccumulatedTotalString = "NOT EQUAL <br>" + "<div class=\"b\" style=\"overflow: hidden;width:110px;\">RESET Total<br>Diff: " + diffAmount + "</div>";
                                    statementTmp.AccumulatedTotalExcel = "NOT EQUAL \n RESET Total \n Diff: " + diffAmount;
                                }
                                statementTmp.AccumulatedTotalNumber = amount - accumAmount;
                            }
                            accumAmount = amount;

                        }
                        else
                        {
                            accumAmount = amount + accumAmount;
                            statementTmp.AccumulatedTotalString = IBCUtils.FormatHandler.FormatNumber20(accumAmount);
                            statementTmp.AccumulatedTotalExcel = IBCUtils.FormatHandler.FormatNumber20(accumAmount);
                            statementTmp.AccumulatedTotalNumber = Math.Round(accumAmount, 2);


                        }

                        int intTransType = 0;//All trans in date
                        if (!string.IsNullOrEmpty(statementTmp.TransDesc))
                        {
                            switch (statementTmp.TransDesc.ToLower())
                            {
                                case "betting statement"://for bets are settled
                                    intTransType = 1;
                                    break;
                                case "void/cancelled bet"://for bets are void and cancelled
                                    intTransType = 2;
                                    break;
                                case "outstanding bet"://for bets are running or waiting
                                    intTransType = 3;
                                    break;
                            }
                        }

                        string transtype = statementTmp.TransType.ToLower();
                        if (transtype == "get" || transtype == "post" || transtype == "com" || transtype == "bet")
                        {
                            statementTmp.BelistLink = "_BetList/BetList.aspx?custid=" + criteria.CustID + "&fdate=" + winlossDatetmp.ToString("MM/dd/yyyy") + "&transtype=" + intTransType + "&type=BLDailyST&username=" + criteria.Username;
                        }
                        else
                        {
                            statementTmp.BelistLink = string.Empty;
                        }

                        statementList.Add(statementTmp);
                    }
                }
            }
            catch (Exception ex)
            {
                LoggingHandler.Log(ex);
            }
            return statementList;
        }

        public MemoryStream ExportExcelStatementMember(StatementMemberCriteria criteria, List<StatementMemberModel> data)
        {
            if (data == null)
            {
                data = (List<StatementMemberModel>)this.GetStatementMember(criteria);
            }

            StatementReportExcelService _reportService = new StatementReportExcelService();

            return _reportService.ExportExcelMemberStatement(criteria, data);
        }
        
    }
